from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalDataResource(Resource):
        def get(self):
            is_legacy = 'localhost' in api_url or 'dev.' in api_url
            verify_ssl = False if is_legacy else True
            try:
                response = requests.get(api_url, verify=verify_ssl)
                response.raise_for_status()
                return response.json()
            except requests.RequestException:
                return {'error': 'Failed to retrieve data'}, 500

    api.add_resource(ExternalDataResource, '/')
    return app

